import { describe, expect, test } from "bun:test";
import {
  adjacentPhase,
  FIRST_PHASE,
  furthestOf,
  PHASES,
  phaseFor,
  phaseImpliedBy,
  reached,
} from "./phases";
import { INITIAL_TEMP, PROMPTS } from "./selector";

const QUESTION_PROMPT_ID = PROMPTS.find((p) => p.isQuestion)?.id ?? "";
const OTHER_PROMPT_ID = PROMPTS.find((p) => !p.isQuestion)?.id ?? "reverse-fn";

describe("era1 phases", () => {
  test("four beats, in the order the presenter walks them", () => {
    expect(PHASES.map((p) => p.id)).toEqual([
      "autocomplete",
      "unanswered",
      "dial",
      "taught",
    ]);
    expect(FIRST_PHASE).toBe("autocomplete");
  });

  test("every arrival loads a prompt that actually exists", () => {
    for (const phase of PHASES) {
      expect(PROMPTS.some((p) => p.id === phase.arrival.promptId)).toBe(true);
    }
  });

  test("only the last beat loads the post-trained model", () => {
    const instruct = PHASES.filter((p) => p.arrival.mode === "instruct");
    expect(instruct.map((p) => p.id)).toEqual(["taught"]);
  });

  test("only the last beat inherits the dial — the rest park it", () => {
    const inherits = PHASES.filter((p) => !p.arrival.resetTemp);
    expect(inherits.map((p) => p.id)).toEqual(["taught"]);
  });

  test("only the beat that is a date carries a year", () => {
    const dated = PHASES.filter((p) => p.year !== undefined);
    expect(dated.map((p) => p.id)).toEqual(["taught"]);
    expect(phaseFor("taught").year).toBe("2022");
  });

  test("reached includes the phase itself and everything behind it", () => {
    expect(reached("dial", "autocomplete")).toBe(true);
    expect(reached("dial", "dial")).toBe(true);
    expect(reached("dial", "taught")).toBe(false);
  });

  test("furthestOf never goes backwards", () => {
    expect(furthestOf("dial", "autocomplete")).toBe("dial");
    expect(furthestOf("autocomplete", "dial")).toBe("dial");
    expect(furthestOf("taught", "taught")).toBe("taught");
  });

  test("the arrows stop at the ends", () => {
    expect(adjacentPhase("autocomplete", "prev")).toBeNull();
    expect(adjacentPhase("autocomplete", "next")).toBe("unanswered");
    expect(adjacentPhase("taught", "next")).toBeNull();
    expect(adjacentPhase("taught", "prev")).toBe("dial");
  });

  test("labels stay out of the engineers' register", () => {
    for (const phase of PHASES) {
      expect(phase.label).not.toContain("//");
      expect(phase.label).not.toContain("▸");
    }
  });

  test("PHASES has exactly four entries — phase-footer.tsx's NUMERALS array is sized to match", () => {
    expect(PHASES.length).toBe(4);
  });

  describe("phaseImpliedBy", () => {
    test("the default config implies the first beat", () => {
      expect(
        phaseImpliedBy({
          mode: "base",
          promptId: OTHER_PROMPT_ID,
          temp: INITIAL_TEMP,
        })
      ).toBe("autocomplete");
    });

    test("the question prompt implies nobody answers", () => {
      expect(
        phaseImpliedBy({
          mode: "base",
          promptId: QUESTION_PROMPT_ID,
          temp: INITIAL_TEMP,
        })
      ).toBe("unanswered");
    });

    test("a moved dial implies turn the dial, even off the function prompt", () => {
      expect(
        phaseImpliedBy({
          mode: "base",
          promptId: OTHER_PROMPT_ID,
          temp: 1.4,
        })
      ).toBe("dial");
    });

    test("instruct mode implies taught to answer, regardless of prompt or temp", () => {
      expect(
        phaseImpliedBy({
          mode: "instruct",
          promptId: OTHER_PROMPT_ID,
          temp: INITIAL_TEMP,
        })
      ).toBe("taught");
    });

    test("instruct mode wins over a moved dial", () => {
      expect(
        phaseImpliedBy({
          mode: "instruct",
          promptId: QUESTION_PROMPT_ID,
          temp: 1.4,
        })
      ).toBe("taught");
    });

    test("a moved dial wins over the question prompt alone", () => {
      expect(
        phaseImpliedBy({
          mode: "base",
          promptId: QUESTION_PROMPT_ID,
          temp: 0.1,
        })
      ).toBe("dial");
    });
  });
});

"use client";

import { cn } from "@repo/design-system/lib/utils";
import { AnimatePresence, motion } from "motion/react";
import type { MouseEvent } from "react";
import { PROMPTS } from "./selector";

const FADE = { duration: 0.25 } as const;

interface PromptTabsProps {
  activeId: string;
  onSelect: (event: MouseEvent<HTMLButtonElement>) => void;
  showSecond: boolean;
}

/**
 * Folder tabs. The active one carries the output panel's exact fill and touches
 * it with no border between, so the two read as one object; the inactive one
 * sits on the console's own background and reads as behind. No underline, no
 * accent colour — the join itself says which prompt is loaded.
 *
 * The fill has to live here rather than on the wrapper: `bg-muted/40` is
 * translucent, so the active tab and the panel only composite to the same
 * colour if both sit directly on the wrapper's `bg-background`.
 */
export function PromptTabs({
  activeId,
  onSelect,
  showSecond,
}: PromptTabsProps) {
  const visible = showSecond ? PROMPTS : PROMPTS.slice(0, 1);
  return (
    <div className="flex h-10 items-stretch gap-1 px-2 pt-2">
      <AnimatePresence initial={false}>
        {visible.map((prompt) => {
          const active = prompt.id === activeId;
          return (
            <motion.button
              animate={{ opacity: 1 }}
              aria-pressed={active}
              className={cn(
                "whitespace-nowrap rounded-t-md px-3 font-mono text-xs transition-colors sm:text-sm",
                active
                  ? "bg-muted/40 text-foreground"
                  : "text-muted-foreground hover:bg-foreground/[0.03] hover:text-foreground"
              )}
              data-prompt={prompt.id}
              exit={{ opacity: 0 }}
              initial={{ opacity: 0 }}
              key={prompt.id}
              onClick={onSelect}
              transition={FADE}
              type="button"
            >
              {prompt.label}
            </motion.button>
          );
        })}
      </AnimatePresence>
    </div>
  );
}

"use client";

import { Button } from "@repo/design-system/components/ui/button";
import { AnimatePresence, motion } from "motion/react";
import type { MouseEvent } from "react";
import { useCallback, useEffect, useRef, useState } from "react";
import { ConsoleChrome } from "./console-chrome";
import { dispositionFor } from "./disposition";
import { PhaseFooter } from "./phase-footer";
import { furthestOf, type PhaseId, phaseFor, phaseImpliedBy } from "./phases";
import { PromptTabs } from "./prompt-tabs";
import {
  bandFor,
  INITIAL_TEMP,
  type Mode,
  OUTPUT_LINES,
  PROMPTS,
  selectCompletion,
} from "./selector";
import {
  type DemoSnapshot,
  freshSnapshot,
  getSnapshot,
  saveSnapshot,
} from "./session-store";
import { verdictFor } from "./verdicts";

const STREAM_MS = 18;

/** Long enough that Eric has already said the line and the page agrees. */
const VERDICT_DELAY_MS = 1500;

/** `OUTPUT_LINES` at leading-7, plus p-4 top and bottom. */
const OUTPUT_HEIGHT = `calc(${OUTPUT_LINES} * 1.75rem + 2rem)`;

const DIAL_WHISPER = "temperature — how much the dice get to decide";

interface Era1PlaygroundProps {
  presenter: boolean;
}

export function Era1Playground({ presenter }: Era1PlaygroundProps) {
  const [snap, setSnap] = useState<DemoSnapshot>(getSnapshot);
  const [streaming, setStreaming] = useState(false);
  const timer = useRef<ReturnType<typeof setInterval> | null>(null);
  const target = useRef("");
  const latest = useRef(snap);

  useEffect(() => {
    latest.current = snap;
    saveSnapshot(snap);
  }, [snap]);

  const stopTimer = useCallback(() => {
    if (timer.current) {
      clearInterval(timer.current);
      timer.current = null;
    }
    setStreaming(false);
  }, []);

  // Navigating away mid-stream stores the *finished* text, so stepping back
  // returns a completed run rather than a sentence cut in half.
  useEffect(
    () => () => {
      if (timer.current) {
        clearInterval(timer.current);
        timer.current = null;
        saveSnapshot({ ...latest.current, output: target.current });
      }
    },
    []
  );

  const patch = useCallback((next: Partial<DemoSnapshot>) => {
    setSnap((s) => ({ ...s, ...next }));
  }, []);

  const run = useCallback(
    (runMode: Mode, runPromptId: string, runTemp: number) => {
      stopTimer();
      const runPrompt = PROMPTS.find((p) => p.id === runPromptId) ?? PROMPTS[0];
      const full = selectCompletion(runPromptId, runTemp, runMode);
      target.current = full;
      const lastRun = {
        band: bandFor(runTemp),
        isQuestion: runPrompt.isQuestion,
        mode: runMode,
      };
      const reduce = window.matchMedia(
        "(prefers-reduced-motion: reduce)"
      ).matches;
      if (reduce) {
        patch({ lastRun, output: full, verdict: null });
        return;
      }
      patch({ lastRun, output: "", verdict: null });
      setStreaming(true);
      let i = 0;
      timer.current = setInterval(() => {
        i += 1;
        setSnap((s) => ({ ...s, output: full.slice(0, i) }));
        if (i >= full.length) {
          stopTimer();
        }
      }, STREAM_MS);
    },
    [patch, stopTimer]
  );

  // The page never speaks first: the verdict arrives a beat after the stream
  // finishes, agreeing with what Eric has already said.
  const { lastRun, verdict } = snap;
  useEffect(() => {
    // The ternary rather than an early return: TypeScript narrows `lastRun`
    // inside the true branch, and the effect returns a cleanup on every path.
    const id =
      !streaming && lastRun !== null && verdict === null
        ? setTimeout(
            () => patch({ verdict: verdictFor(lastRun) }),
            VERDICT_DELAY_MS
          )
        : null;
    return () => {
      if (id) {
        clearTimeout(id);
      }
    };
  }, [lastRun, patch, streaming, verdict]);

  const handleRun = useCallback(
    () => run(snap.mode, snap.promptId, snap.temp),
    [run, snap.mode, snap.promptId, snap.temp]
  );

  const goToPhase = useCallback(
    (id: PhaseId) => {
      stopTimer();
      const { arrival } = phaseFor(id);
      setSnap((s) => ({
        ...s,
        furthest: furthestOf(s.furthest, id),
        lastRun: null,
        mode: arrival.mode,
        output: "",
        phase: id,
        promptId: arrival.promptId,
        temp: arrival.resetTemp ? INITIAL_TEMP : s.temp,
        verdict: null,
      }));
    },
    [stopTimer]
  );

  const handleModeChange = useCallback(
    (next: Mode) => {
      stopTimer();
      setSnap((s) =>
        s.mode === next
          ? s
          : { ...s, lastRun: null, mode: next, output: "", verdict: null }
      );
    },
    [stopTimer]
  );

  const handlePromptClick = useCallback(
    (event: MouseEvent<HTMLButtonElement>) => {
      const id = event.currentTarget.dataset.prompt;
      if (!id) {
        return;
      }
      stopTimer();
      setSnap((s) =>
        s.promptId === id
          ? s
          : { ...s, lastRun: null, output: "", promptId: id, verdict: null }
      );
    },
    [stopTimer]
  );

  const handleReset = useCallback(() => {
    stopTimer();
    setSnap(freshSnapshot());
  }, [stopTimer]);

  const handleTempChange = useCallback(
    (temp: number) => patch({ temp }),
    [patch]
  );

  // A control left in a later-beat state (dial moved, mode flipped) implies
  // that later beat even if `furthest`/`phase` haven't caught up — e.g.
  // toggling presenter mode on mid-session. Folding it into both keeps the
  // disposition and the footer's highlight consistent with what's on screen;
  // `furthestOf` is monotone both ways, so this only ever opens gates and
  // advances the highlight, never closes or rewinds them.
  const implied = phaseImpliedBy({
    mode: snap.mode,
    promptId: snap.promptId,
    temp: snap.temp,
  });
  const furthest = furthestOf(snap.furthest, implied);
  const phase = furthestOf(snap.phase, implied);

  const disposition = dispositionFor({
    furthest,
    presenter,
  });
  const prompt = PROMPTS.find((p) => p.id === snap.promptId) ?? PROMPTS[0];

  // One slot, one line: the run's verdict, or the dial's whisper before any
  // run, or nothing. Both regions this replaces used to appear and disappear.
  const line =
    snap.verdict ??
    (disposition.showDial && snap.lastRun === null ? DIAL_WHISPER : "");

  return (
    <div className="mb-6">
      <div className="overflow-hidden rounded-xl border border-foreground/10 bg-background">
        <ConsoleChrome
          mode={snap.mode}
          onModeChange={handleModeChange}
          onReset={handleReset}
          onTempChange={handleTempChange}
          showDial={disposition.showDial}
          showPostTrainedCell={disposition.showPostTrainedCell}
          temp={snap.temp}
        />

        <div className="p-4 sm:p-6">
          <div className="overflow-hidden rounded-lg border border-foreground/10 bg-background">
            <PromptTabs
              activeId={snap.promptId}
              onSelect={handlePromptClick}
              showSecond={disposition.showSecondPrompt}
            />
            <pre
              className="overflow-auto whitespace-pre-wrap bg-muted/40 p-4 font-mono text-[15px] leading-7"
              style={{ height: OUTPUT_HEIGHT }}
            >
              <span className="text-foreground">{prompt.prefix}</span>
              <span className="text-ht-cyan-700 dark:text-ht-cyan-300">
                {snap.output}
              </span>
              {streaming ? <span className="animate-pulse">▋</span> : null}
            </pre>
          </div>

          <div className="mt-4 flex justify-end">
            <Button onClick={handleRun} type="button">
              Run ⏎
            </Button>
          </div>
        </div>

        <div
          aria-live="polite"
          className="flex min-h-14 items-center border-foreground/10 border-t px-4 py-2 sm:h-14 sm:px-6 sm:py-0"
          role="status"
        >
          <AnimatePresence mode="wait">
            {line ? (
              <motion.p
                animate={{ opacity: 1 }}
                className="max-w-2xl text-foreground/55 text-sm italic"
                exit={{ opacity: 0 }}
                initial={{ opacity: 0 }}
                key={line}
                transition={{ duration: 0.35 }}
              >
                {line}
              </motion.p>
            ) : null}
          </AnimatePresence>
        </div>

        {disposition.showFooter ? (
          <PhaseFooter current={phase} onSelect={goToPhase} />
        ) : null}
      </div>
    </div>
  );
}

