() => {
  const qa = (s) => [...document.querySelectorAll(s)];
  const nav = document.querySelector('nav[aria-label="Demo beats"]');
  const beatBtn = (n) => qa('nav[aria-label="Demo beats"] button').filter(b => /^[1-4]$/.test(b.textContent.trim()))[n-1];
  const run = () => qa('button').find(b => /^Run/.test(b.textContent.trim())).click();
  const setTemp = (v) => {
    const s = document.querySelector('[role="slider"]');
    s.focus();
    const key = v === 'hot' ? 'End' : 'Home';
    s.dispatchEvent(new KeyboardEvent('keydown', { key, bubbles: true }));
  };
  beatBtn(3).click();
  return new Promise(res => setTimeout(() => {
    const onArrival = {
      beatLabel: nav.querySelector('div:last-child')?.textContent.trim(),
      dialPresent: !!document.querySelector('[role="slider"]'),
      temp: document.querySelector('[role="slider"]')?.getAttribute('aria-valuenow'),
      statusBeforeRun: document.querySelector('[role="status"] p')?.textContent ?? '(empty)',
    };
    setTemp('hot');
    setTimeout(() => {
      const hotTemp = document.querySelector('[role="slider"]').getAttribute('aria-valuenow');
      run();
      setTimeout(() => {
        const hotVerdict = document.querySelector('[role="status"] p')?.textContent;
        const hotOut = document.querySelector('pre')?.textContent.replace(/\n/g,'\\n').slice(40,120);
        setTemp('cold');
        setTimeout(() => {
          const coldTemp = document.querySelector('[role="slider"]').getAttribute('aria-valuenow');
          run();
          setTimeout(() => res({
            beat: 3, onArrival,
            hot: { temp: hotTemp, verdict: hotVerdict, output: hotOut },
            cold: { temp: coldTemp, verdict: document.querySelector('[role="status"] p')?.textContent,
                    output: document.querySelector('pre')?.textContent.replace(/\n/g,'\\n').slice(40,120) },
          }), 8000);
        }, 400);
      }, 8000);
    }, 400);
  }, 500));
}

