() => {
  const qa = (s) => [...document.querySelectorAll(s)];
  const beatBtn = (n) => qa('nav[aria-label="Demo beats"] button').filter(b => /^[1-4]$/.test(b.textContent.trim()))[n-1];
  const slot = () => {
    const el = document.querySelector('[role="status"]');
    return { text: el?.textContent.trim() || '(empty)', height: Math.round(el.getBoundingClientRect().height) };
  };
  qa('button').find(b => b.getAttribute('aria-label') === 'Start the demo over').click();
  const results = [];
  const step = (n) => new Promise(r => {
    beatBtn(n).click();
    setTimeout(() => { results.push({ beat: n, onArrival: slot() }); r(); }, 700);
  });
  return (async () => {
    await new Promise(r => setTimeout(r, 600));
    results.push({ afterReset: slot() });
    for (const n of [1, 2, 3, 4, 3, 1]) await step(n);
    return results;
  })();
}

