export function fingerprintSources(
  sources: { continuations: Record<string, string>; id: string; instructAnswers: Record<string, string>; prefix: string }[]
): string {
  const parts: string[] = [];
  for (const p of [...sources].sort((a, b) => a.id.localeCompare(b.id))) {
    parts.push(p.id, p.prefix);
    for (const band of ["high", "low", "mid"]) {
      parts.push(p.continuations[band], p.instructAnswers[band]);
    }
  }

