() => {
  const qa = (s) => [...document.querySelectorAll(s)];
  const runBtn = () => qa('button').find(b => /^Run/.test(b.textContent.trim()));
  const pos = () => { const r = runBtn().getBoundingClientRect(); return `${Math.round(r.x)},${Math.round(r.y)}`; };
  const pre = document.querySelector('pre');
  const preH = Math.round(pre.getBoundingClientRect().height);
  const positions = new Set([pos()]);
  const classSamples = [];
  runBtn().click();
  return new Promise(res => {
    const id = setInterval(() => {
      positions.add(pos());
      const spans = [...pre.querySelectorAll('span')];
      classSamples.push(spans.slice(0, 6).map(s => s.className).join('|'));
    }, 100);
    setTimeout(() => {
      clearInterval(id);
      const spans = [...pre.querySelectorAll('span')];
      const cyan = spans.filter(s => s.className.includes('ht-cyan'));
      const themed = spans.filter(s => !s.className.includes('ht-cyan'));
      res({
        runButtonPositions: [...positions],
        preHeightBefore: preH,
        preHeightAfter: Math.round(pre.getBoundingClientRect().height),
        prefixSpanCount: themed.length,
        completionSpanCount: cyan.length,
        distinctPrefixColours: [...new Set(themed.map(s => getComputedStyle(s).color))],
        distinctCompletionColours: [...new Set(cyan.map(s => getComputedStyle(s).color))],
        firstSixClassesStable: new Set(classSamples.filter(Boolean)).size,
        renderedText: spans.map(s => s.textContent).join('').slice(0, 70).replace(/\n/g, '\\n'),
      });
    }, 8000);
  });
}

