            textUnchangedAfterDrag: afterRun === afterDrag,
            stillHighBand: afterDrag.includes('reverse time'),
            sample: afterDrag.slice(41, 110).replace(/\n/g, '\\n'),
          });
        }, 800);
      }, 8000);
    }, 400);
  }, 600));
}

