() => {
  const pre = document.querySelector('pre');
  const spans = [...pre.querySelectorAll('span')];
  const bg = getComputedStyle(pre.parentElement).backgroundColor;
  const parse = (c) => {
    const m = c.match(/[\d.]+/g).map(Number);
    return { r: m[0], g: m[1], b: m[2], a: m[3] ?? 1 };
  };
  const lum = ({ r, g, b }) => {
    const f = (v) => { v /= 255; return v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4; };
    return 0.2126 * f(r) + 0.7152 * f(g) + 0.0722 * f(b);
  };
  const over = (fg, back) => ({
    r: fg.r * fg.a + back.r * (1 - fg.a),
    g: fg.g * fg.a + back.g * (1 - fg.a),
    b: fg.b * fg.a + back.b * (1 - fg.a),
  });
  const bgc = parse(bg);
  const contrast = (c) => {
    const eff = over(parse(c), bgc);
    const l1 = lum(eff), l2 = lum(bgc);
    return +(((Math.max(l1, l2) + 0.05) / (Math.min(l1, l2) + 0.05))).toFixed(2);
  };
  const byKind = {};
  for (const s of spans) {
    const cyan = s.className.includes('ht-cyan');
    const key = (cyan ? 'completion' : 'prefix') + (s.className.includes('/55') ? ':comment55' : cyan ? ':other' : '');
    const c = getComputedStyle(s).color;
    byKind[key] ??= { colour: c, contrast: contrast(c), sample: s.textContent.slice(0, 22) };
  }
  return { panelBg: bg, byKind };
}

