export function fingerprintSources(prompts: readonly PromptSeed[]): string {
  const parts: string[] = [];
  for (const p of [...prompts].sort((a, b) => a.id.localeCompare(b.id))) {
    parts.push(p.id, p.prefix);
    for (const band of ["high", "low", "mid"] as const) {
